check.check-content:
Run the following script and verify the output:
#!/usr/bin/env bash
{
while IFS= read -r l_file; do
awk '/\[xdmcp\]/{ f = 1;next } /\[/{ f = 0 } f {if (/^\s*Enable\s*=\s*true/) print "The file:
\"'"$l_file"'\" includes: \"" $0 "\" in the \"[xdmcp]\" block"}' "$l_file"
done < <(grep -Psil -- '^\h*\[xdmcp\]' /etc/{gdm3,gdm}/{custom,daemon}.conf)
}
Nothing should be returned Internal Only - General

Rule.fixtext:
Set the following parameter in /etc/sysctl.conf or a file in /etc/sysctl.d/ ending in.conf:
• net.ipv4.ip_forward = 0 Example:
# printf '%s\n' "net.ipv4.ip_forward = 0" >> /etc/sysctl.d/60-netipv4_sysctl.conf
Run the following script to set the active kernel parameters:
#!/usr/bin/env bash
{
sysctl -w net.ipv4.ip_forward=0
sysctl -w net.ipv4.route.flush=1
}
- IF - IPv6 is enabled on the system:
Set the following parameter in /etc/sysctl.conf or a file in /etc/sysctl.d/ ending in.conf:
• net.ipv6.conf.all.forwarding = 0 Example:
# printf '%s\n' "net.ipv6.conf.all.forwarding = 0" >> /etc/sysctl.d/60-netipv6_sysctl.conf
Run the following script to set the active kernel parameters:
#!/usr/bin/env bash
{
sysctl -w net.ipv6.conf.all.forwarding=0
sysctl -w net.ipv6.route.flush=1
}
Note: If these settings appear in a canonically later file, or later in the same file, these settings will be overwritten

Set the following parameter in /etc/sysctl.conf or a file in /etc/sysctl.d/ ending in.conf:
• net.ipv4.icmp_ignore_bogus_error_responses = 1 Example:
# printf '%s\n' "net.ipv4.icmp_ignore_bogus_error_responses = 1" >> /etc/sysctl.d/60-netipv4_sysctl.conf
Run the following script to set the active kernel parameters:
#!/usr/bin/env bash
{
sysctl -w net.ipv4.icmp_ignore_bogus_error_responses=1
sysctl -w net.ipv4.route.flush=1
}
Note: If these settings appear in a canonically later file, or later in the same file, these settings will be overwritten

Set the following parameter in /etc/sysctl.conf or a file in /etc/sysctl.d/ ending in.conf:
• net.ipv4.icmp_echo_ignore_broadcasts = 1 Example:
# printf '%s\n' "net.ipv4.icmp_echo_ignore_broadcasts = 1" >> /etc/sysctl.d/60-netipv4_sysctl.conf
Run the following script to set the active kernel parameters:
#!/usr/bin/env bash
{
sysctl -w net.ipv4.icmp_echo_ignore_broadcasts=1
sysctl -w net.ipv4.route.flush=1
}
Note: If these settings appear in a canonically later file, or later in the same file, these settings will be overwritten

Set the following parameter in /etc/sysctl.conf or a file in /etc/sysctl.d/ ending in.conf:
• net.ipv4.tcp_syncookies = 1 Example:
# printf '%s\n' "net.ipv4.tcp_syncookies = 1" >> /etc/sysctl.d/60-netipv4_sysctl.conf
Run the following script to set the active kernel parameters:
#!/usr/bin/env bash
{
sysctl -w net.ipv4.tcp_syncookies=1
sysctl -w net.ipv4.route.flush=1
}
Note: If these settings appear in a canonically later file, or later in the same file, these settings will be overwritten

Run the following command to create the base chains:
# nft create chain inet <table name> <base chain name> { type filter hook <(input|forward|output)> priority 0
\; }
Example:
# nft create chain inet filter input { type filter hook input priority 0 \; }
# nft create chain inet filter forward { type filter hook forward priority 0 \; }
# nft create chain inet filter output { type filter hook output priority 0 \; }

check.check-content:
Run the following commands and verify that base chains exist for INPUT.
# nft list ruleset | grep 'hook input'
type filter hook input priority 0;
Run the following commands and verify that base chains exist for FORWARD.
# nft list ruleset | grep 'hook forward'
type filter hook forward priority 0;
Run the following commands and verify that base chains exist for OUTPUT.
# nft list ruleset | grep 'hook output'
type filter hook output priority 0;
Internal Only - General

Rule.fixtext:
Run the following command for the base chains with the input, forward, and output hooks to implement a default DROP policy:
# nft chain <table family> <table name> <chain name> { policy drop \; }
Example:
# nft chain inet filter input { policy drop \; }
# nft chain inet filter forward { policy drop \; }
# nft chain inet filter output { policy drop \; }

check.check-content:
Run the following commands and verify that base chains contain a policy of DROP.
# nft list ruleset | grep 'hook input'
type filter hook input priority 0; policy drop;
# nft list ruleset | grep 'hook forward'
type filter hook forward priority 0; policy drop;
# nft list ruleset | grep 'hook output'
type filter hook output priority 0; policy drop;
Internal Only - General

Rule.fixtext:
Run the following script to set mode, ownership, and group on the private SSH host key files: #!/usr/bin/env bash { a_output=(); a_output2=(); l_ssh_group_name="$(awk -F: '($1 ~ /^(ssh_keys|_?ssh)$/) {print $1}' /etc/group)" f_file_access_fix() { while IFS=: read -r l_file_mode l_file_owner l_file_group; do a_out2=() [ "$l_file_group" = "$l_ssh_group_name" ] && l_pmask="0137" || l_pmask="0177" l_maxperm="$( printf '%o' $(( 0777 & ~$l_pmask )) )" if [ $(( $l_file_mode & $l_pmask )) -gt 0 ]; then a_out2+=(" Mode: "$l_file_mode" should be mode: "$l_maxperm" or more restrictive" \ " updating to mode: \:$l_maxperm"") if [ "l_file_group" = "$l_ssh_group_name" ]; then chmod u-x,g-wx,o-rwx "$l_file" else chmod u-x,go-rwx "$l_file" fi fi if [ "$l_file_owner" != "root" ]; then a_out2+=(" Owned by: "$l_file_owner" should be owned by "root"" \ " Changing ownership to "root"") chown root "$l_file" fi if [[ ! "$l_file_group" =~ ($l_ssh_group_name|root) ]]; then [ -n "$l_ssh_group_name" ] && l_new_group="$l_ssh_group_name" || l_new_group="root" a_out2+=(" Owned by group "$l_file_group" should be group owned by: "$l_ssh_group_name" or "root"" \ " Changing group ownership to "$l_new_group"") chgrp "$l_new_group" "$l_file" fi if [ "${#a_out2[@]}" -gt "0" ]; then a_output2+=(" - File: "$l_file"" "${a_out2[@]}") else a_output+=(" - File: "$l_file"" \ "Correct: mode: "$l_file_mode", owner: "$l_file_owner", and group owner: "$l_file_group" configured") fi done < <(stat -Lc '%#a:%U:%G' "$l_file") } while IFS= read -r -d $'\0' l_file; do if ssh-keygen -lf &>/dev/null "$l_file"; then file "$l_file" | grep -Piq -- ' openssh\h+([^#
]+\h+)?private\h+key ' && f_file_access_fix fi done < <(find -L /etc/ssh -xdev -type f -print0 2>/dev/null) if [ "${#a_output2[@]}" -le "0" ]; then printf '%s
' "" " - No access changes required" "" else printf '%s
' "" " - Remediation results:" "${a_output2[@]}" "" fi }

Run the following script to set mode, ownership, and group on the public SSH host key files: #!/usr/bin/env bash { a_output=(); a_output2=() l_pmask="0133"; l_maxperm="$( printf '%o' $(( 0777 & ~$l_pmask )) )" f_file_access_fix() { while IFS=: read -r l_file_mode l_file_owner l_file_group; do a_out2=() [ $(( $l_file_mode & $l_pmask )) -gt 0 ] && \ a_out2+=(" Mode: "$l_file_mode" should be mode: "$l_maxperm" or more restrictive" \ " updating to mode: "$l_maxperm"") && chmod u-x,go-wx "$l_file" [ "$l_file_owner" != "root" ] && \ a_out2+=(" Owned by: "$l_file_owner" should be owned by "root"" \ " Changing ownership to "root"") && chown root "$l_file" [ "$l_file_group" != "root" ] && \ a_out2+=(" Owned by group "$l_file_group" should be group owned by: "root"" \ " Changing group ownership to "root"") && chgrp root "$l_file" if [ "${#a_out2[@]}" -gt "0" ]; then a_output2+=(" - File: "$l_file"" "${a_out2[@]}") else a_output+=(" - File: "$l_file"" \ " Correct: mode: "$l_file_mode", owner: "$l_file_owner", and group owner: "$l_file_group" configured") fi done < <(stat -Lc '%#a:%U:%G' "$l_file") } while IFS= read -r -d $'\0' l_file; do if ssh-keygen -lf &>/dev/null "$l_file"; then file "$l_file" | grep -Piq -- ' openssh\h+([^#
]+\h+)?public\h+key ' && f_file_access_fix fi done < <(find -L /etc/ssh -xdev -type f -print0 2>/dev/null) if [ "${#a_output2[@]}" -le "0" ]; then printf '%s
' "" " - No access changes required" "" else printf '%s
' " - Remediation results:" "${a_output2[@]}" "" fi }

Run the following command: # grep -Pl -- ' pam_pwquality\.so\h+([^#
]+\h+)?(minclass|[dulo]credit) ' /usr/share/pam-configs/* Edit any returned files and remove the minclass, dcredit, ucredit, lcredit, and ocredit arguments from the pam_pwquality.so line(s) Create or modify a file ending in.conf in the /etc/security/pwquality.conf.d/ directory or the file /etc/security/pwquality.conf and add or modify the following line(s) to set complexity according to local site policy: • minclass = _N_ • dcredit = _N_ # Value should be either 0 or a number proceeded by a minus ( - ) symbol • ucredit = -1 # Value should be either 0 or a number proceeded by a minus ( -) symbol • ocredit = -1 # Value should be either 0 or a number proceeded by a minus ( -) symbol • lcredit = -1 # Value should be either 0 or a number proceeded by a minus ( -) symbol Example 1 - Set minclass = 3: #!/usr/bin/env bash { sed -ri 's/^\s*minclass\s*=/# &/' /etc/security/pwquality.conf sed -ri 's/^\s*[dulo]credit\s*=/# &/' /etc/security/pwquality.conf [ ! -d /etc/security/pwquality.conf.d/ ] && mkdir /etc/security/pwquality.conf.d/ printf '
%s' "minclass = 3" > /etc/security/pwquality.conf.d/50-pwcomplexity.conf } Example 2 - set dcredit = -1, ucredit = -1, and lcredit = -1: #!/usr/bin/env bash { sed -ri 's/^\s*minclass\s*=/# &/' /etc/security/pwquality.conf sed -ri 's/^\s*[dulo]credit\s*=/# &/' /etc/security/pwquality.conf [ ! -d /etc/security/pwquality.conf.d/ ] && mkdir /etc/security/pwquality.conf.d/ printf '%s
' "dcredit = -1" "ucredit = -1" "lcredit = -1" > /etc/security/pwquality.conf.d/50- pwcomplexity.conf }

Edit or add the following line in a *.conf file in /etc/security/pwquality.conf.d or in /etc/security/pwquality.conf:
Example:
#!/usr/bin/env bash
{
[ ! -d /etc/security/pwquality.conf.d/ ] && mkdir /etc/security/pwquality.conf.d/
printf '\n%s\n' "enforce_for_root" > /etc/security/pwquality.conf.d/50-pwroot.conf
}

check.check-content:
Run the following command to verify system accounts, except for root, halt, sync, shutdown or nfsnobody, do not have a valid login shell:
#!/usr/bin/env bash
{
l_valid_shells="^($(awk -F\/ '$NF != "nologin" {print}' /etc/shells | sed -rn '/^\//{s,/,\\\\/,g;p}' | paste
-s -d '|' - ))$"
awk -v pat="$l_valid_shells" -F: '($1!~/^(root|halt|sync|shutdown|nfsnobody)$/ && ($3<'"$(awk
'/^\s*UID_MIN/{print $2}' /etc/login.defs)"' || $3 == 65534) && $(NF) ~ pat) {print "Service account: \"" $1
"\" has a valid shell: " $7}' /etc/passwd
}
Nothing should be returned Internal Only - General

Run the following script to verify that TMOUT is configured to: include a timeout of no more than 900 seconds, to be readonly, to be exported, and is not being changed to a longer timeout. #!/usr/bin/env bash { a_output=(); a_output2=(); l_tmout_set="900" f_tmout_read_chk() { a_out=(); a_out2=() l_tmout_readonly="$(grep -P -- '^\h*(typeset\h\-xr\hTMOUT=\d+|([^#
]+)? readonly\h+TMOUT )' "$l_file")" l_tmout_export="$(grep -P -- '^\h*(typeset\h\-xr\hTMOUT=\d+|([^#
]+)? export ([^#
]+ )?TMOUT )' "$l_file")" if [ -n "$l_tmout_readonly" ]; then a_out+=(" - Readonly is set as: "$l_tmout_readonly" in: "$l_file"") else a_out2+=(" - Readonly is not set in: "$l_file"") fi if [ -n "$l_tmout_export" ]; then a_out+=(" - Export is set as: "$l_tmout_export" in: "$l_file"") else a_out2+=(" - Export is not set in: "$l_file"") fi } while IFS= read -r l_file; do l_tmout_value="$(grep -Po -- '^([^#
]+)? TMOUT=\d+ ' "$l_file" | awk -F= '{print $2}')" f_tmout_read_chk if [ -n "$l_tmout_value" ]; then if [[ "$l_tmout_value" -le "$l_tmout_set" && "$l_tmout_value" -gt "0" ]]; then a_output+=(" - TMOUT is set to: "$l_tmout_value" in: "$l_file"") [ "${#a_out[@]}" -gt 0 ] && a_output+=("${a_out[@]}") [ "${#a_out2[@]}" -gt 0 ] && a_output2+=("${a_out[@]}") fi if [[ "$l_tmout_value" -gt "$l_tmout_set" || "$l_tmout_value" -le "0" ]]; then a_output2+=(" - TMOUT is incorrectly set to: "$l_tmout_value" in: "$l_file"") [ "${#a_out[@]}" -gt 0 ] && a_output2+=(" ** Incorrect TMOUT value **" "${a_out[@]}") [ "${#a_out2[@]}" -gt 0 ] && a_output2+=("${a_out2[@]}") fi else [ "${#a_out[@]}" -gt 0 ] && a_output2+=(" - TMOUT is not set" "${a_out[@]}") [ "${#a_out2[@]}" -gt 0 ] && a_output2+=(" - TMOUT is not set" "${a_out2[@]}") fi done < <(grep -Pls -- '^([^#
]+)? TMOUT ' /etc/*bashrc /etc/profile /etc/profile.d/*.sh) [[ "${#a_output[@]}" -le 0 && "${#a_output2[@]}" -le 0 ]] && a_output2+=(" - TMOUT is not configured") if [ "${#a_output2[@]}" -le 0 ]; then printf '%s
' "" "- Audit Result:" " ** PASS **" "${a_output[@]}" else printf '%s
' "" "- Audit Result:" " ** FAIL **" " * Reasons for audit failure *" "${a_output2[@]}" "" [ "${#a_output[@]}" -gt 0 ] && printf '%s
' "- Correctly set:" "${a_output[@]}" fi } Note: If TMOUT is set as readonly through readonly TMOUT and/or typeset -xr in more than once, you will receive an error message when logging into a terminal session or connecting with openSSH. It is recommended that TMOUT be set only once in only one file. Internal Only - General

Run the following script to analyze the logrotate configuration:
#!/usr/bin/env bash
{
l_analyze_cmd="$(readlink -f /bin/systemd-analyze)" l_config_file="/etc/logrotate.conf"
l_include="$(awk '$1~/^\s*include$/{print$2}' "$l_config_file" 2>/dev/null)"
[ -d "$l_include" ] && l_include="$l_include/*"
$l_analyze_cmd cat-config "$l_config_file" $l_include
}
Note: The last occurrence of a argument is the one used for the logrotate configuration

Run the following script and verify no results are returned:
#!/usr/bin/env bash
{
while read -r l_count l_uid; do
if [ "$l_count" -gt 1 ]; then
echo -e "Duplicate UID: \"$l_uid\" Users: \"$(awk -F: '($3 == n) { print $1 }' n=$l_uid /etc/passwd |
xargs)\""
fi
done < <(cut -f3 -d":" /etc/passwd | sort -n | uniq -c)
}

